head.script:
scwin.__simulate = function() {
    WebSquare.wUnit.getJq("#wq_uuid_1___input").simulate("key-sequence", {
        sequence: "here",
        delay: 100
    });
}
scwin.___isIE = function() {
    var myNav = navigator.userAgent.toLowerCase();
    if (myNav.indexOf('msie') != -1) {
        return parseInt(myNav.split('msie')[1]);
    } else if (myNav.substr(myNav.indexOf('rv') + 3, 2) == "11" || myNav.substr(myNav.indexOf('rv') + 2, 2) == "16") {
        return true;
    } else {
        return false;
    }
}
scwin.__hasOneIcon = function() {
    return scwin.___isIE() ? WebSquare.wUnit.getJq("#wq_uuid_1___input").hasClass("w2searchbox_reset_remove") : true;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 입력박스에 값을 입력한다.
    //1. Run the sample file and enter a value in the input box.
    WebSquare.wUnit.addCommand("set", "scwin.__simulate()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 1. 값이 입력된 상태에서 닫기(x)가 1개만 보여진다.(Edge에서 이전에는 닫기(x)가 2개 보여짐
    //1. With the value entered, only one close (x) is shown.(Two close (x) were previously seen on the Edge.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_1___input').val()", "here");
    WebSquare.wUnit.addCommand("assert", "scwin.__hasOneIcon()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 09-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
